-- high_value_cards (index bank-dept-*)
SELECT * FROM bank_dept_all
WHERE ((dept = "cards") AND (amount >= 1000)) AND NOT (status = "reversal");

-- suspicious_narratives (index bank-statements-*)
SELECT * FROM bank_statements_all
WHERE ((lower(body) LIKE '%overdraft%') OR (lower(body) LIKE '%unauthorized%'));
